<div class="page-heading"><div><p class="eyebrow">Administration · CMS</p><h1>Site content</h1><p>Public copy is read from MySQL. Text is displayed as plain text, not executable HTML.</p></div></div>
<section class="panel" style="margin-bottom:18px"><h2 class="panel-title">Add content entry</h2><form method="post" action="<?= h(app_url('admin.cms.save')) ?>" class="form-grid" data-submit-feedback><?= csrf_field() ?><div class="form-field"><label for="new-key">Content key</label><input id="new-key" name="content_key" maxlength="100" placeholder="page.faq" value="<?= h(old('content_key')) ?>"<?= form_field_invalid_attr('content_key') ?> required><?= field_error_html('content_key') ?></div><div class="form-field"><label for="new-title">Title</label><input id="new-title" name="title" maxlength="180" value="<?= h(old('title')) ?>"<?= form_field_invalid_attr('title') ?> required><?= field_error_html('title') ?></div><div class="form-field"><label for="new-section">Section</label><input id="new-section" name="section" maxlength="40" value="<?= h(old('section', 'page')) ?>"<?= form_field_invalid_attr('section') ?> required><?= field_error_html('section') ?></div><div class="form-field"><label for="new-image">Image <span class="muted">(optional)</span></label><select id="new-image" name="image_media_id"><option value="0">No image</option><?php foreach ($mediaChoices as $mediaChoice): ?><option value="<?= (int) $mediaChoice['id'] ?>"<?= old_selected('image_media_id', $mediaChoice['id']) ? ' selected' : '' ?>><?= h($mediaChoice['original_name']) ?> · #<?= (int) $mediaChoice['id'] ?></option><?php endforeach; ?></select><span class="field-hint"><a href="<?= h(app_url('admin.media')) ?>">Upload or manage images</a></span></div><div class="form-field full"><label for="new-body">Body</label><textarea id="new-body" name="body" maxlength="10000" rows="3"<?= form_field_invalid_attr('body') ?>><?= h(old('body')) ?></textarea><?= field_error_html('body') ?></div><div class="form-field full"><label class="check-row"><input type="checkbox" name="is_published"<?= old_checked('is_published', true) ? ' checked' : '' ?>><span>Published</span></label></div><div class="form-field full"><button class="button" type="submit" data-loading-text="Saving…">Add content</button></div></form></section>
<div class="stack"><?php foreach ($content as $entry): ?><details class="panel cms-entry"><summary><strong><?= h($entry['title']) ?></strong><span class="muted small"> · <?= h($entry['content_key']) ?> · <?= h($entry['section']) ?> · <?= $entry['is_published']?'Published':'Draft' ?></span></summary>
<form method="post" action="<?= h(app_url('admin.cms.save')) ?>" class="form-grid" style="margin-top:16px" data-submit-feedback><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$entry['id'] ?>"><div class="form-field"><label for="key-<?= (int)$entry['id'] ?>">Content key</label><input id="key-<?= (int)$entry['id'] ?>" name="content_key" maxlength="100" value="<?= h($entry['content_key']) ?>" required></div><div class="form-field"><label for="title-<?= (int)$entry['id'] ?>">Title</label><input id="title-<?= (int)$entry['id'] ?>" name="title" maxlength="180" value="<?= h($entry['title']) ?>" required></div><div class="form-field"><label for="section-<?= (int)$entry['id'] ?>">Section</label><input id="section-<?= (int)$entry['id'] ?>" name="section" maxlength="40" value="<?= h($entry['section']) ?>" required></div><div class="form-field"><label for="media-<?= (int)$entry['id'] ?>">Image <span class="muted">(optional)</span></label><select id="media-<?= (int)$entry['id'] ?>" name="image_media_id"><option value="0"<?= empty($entry['image_media_id']) ? ' selected' : '' ?>>No image</option><?php if (!empty($entry['image_media_id'])): ?><option value="<?= (int) $entry['image_media_id'] ?>" selected><?= h($entry['media_name'] ?? 'Current image') ?> · #<?= (int) $entry['image_media_id'] ?></option><?php endif; ?><?php foreach ($mediaChoices as $mediaChoice): if ((int) $mediaChoice['id'] !== (int) ($entry['image_media_id'] ?? 0)): ?><option value="<?= (int) $mediaChoice['id'] ?>"><?= h($mediaChoice['original_name']) ?> · #<?= (int) $mediaChoice['id'] ?></option><?php endif; endforeach; ?></select><span class="field-hint"><a href="<?= h(app_url('admin.media')) ?>">Upload or manage images</a></span></div><div class="form-field full"><label for="body-<?= (int)$entry['id'] ?>">Body</label><textarea id="body-<?= (int)$entry['id'] ?>" name="body" maxlength="10000" rows="4"><?= h($entry['body']??'') ?></textarea></div><div class="form-field full"><label class="check-row"><input type="checkbox" name="is_published"<?= $entry['is_published']?' checked':'' ?>><span>Published</span></label></div><div class="form-field full"><div class="spread"><span class="muted tiny">Last updated <?= h(format_datetime($entry['updated_at'])) ?><?= $entry['editor']?' by '.h($entry['editor']):'' ?></span><button class="button button-secondary button-small" type="submit" data-loading-text="Saving…">Save content</button></div></div></form></details><?php endforeach; ?></div>
